// app/groups/[groupId]/events/[eventId]/carpool/page.tsx (settlement/page.tsx와 동일 골격)
async function CarpoolSection({params}) {
  const {groupId, eventId} = await params;
  const supabase = await createClient();
  const {data:auth} = await supabase.auth.getClaims();
  if (!auth?.claims) redirect('/auth/login');
  // group_members 조회 -> isAdmin 계산 (기존 event/settlement 페이지와 동일 패턴 반복)
  const offers = await supabase.from('carpool_offers').select('...').eq('event_id', eventId);
  const requests = await supabase.from('carpool_requests').select('...').eq('event_id', eventId);
  const matches = await supabase.from('carpool_matches').select('...offer(...),request(...)');
  return <>{offer/request 목록 Table} <CarpoolOfferForm/> <CarpoolRequestForm/> {isAdmin && <매칭 실행 버튼(action)>}</>
}

// app/groups/[groupId]/events/[eventId]/carpool/actions.ts
'use server'
export async function runMatching({eventId}) {
  const supabase = await createClient();
  const {error} = await supabase.rpc('run_carpool_matching', {p_event_id: eventId});
  if (error) return {error: error.message};
  revalidatePath(`/groups/.../carpool`);
  return {success:true};
}

// components/carpool/carpool-offer-form.tsx, carpool-request-form.tsx
